pub const bun = @import("bun");
pub const crash_handler_jsc = @import("../runtime/api/crash_handler_jsc.zig");
pub const CrashReason = union(enum) {
    panic: []const u8,
    @"unreachable",
    segmentation_fault: usize,
    illegal_instruction: usize,
    bus_error: usize,
    floating_point_error: usize,
    datatype_misalignment,
    stack_overflow,
    zig_error: anyerror,
    out_of_memory,
    pub fn has(s: []const u8) bool { if (comptime @typeInfo(@This()).@"union".tag_type) |TagType| { return std.meta.stringToEnum(TagType, s) != null; } return false; }
    pub fn name(self: @This()) []const u8 { return @tagName(self); }

pub fn format(reason: CrashReason, writer: *std.Io.Writer) !void {
            switch (reason) {
.panic => |message| {
_ = try writer.print("{s}", .{ message });
},
.@"unreachable" => {
_ = try writer.writeAll("reached unreachable code");
},
.segmentation_fault => |addr| {
_ = try writer.print("Segmentation fault at address 0x{X}", .{ addr });
},
.illegal_instruction => |addr| {
_ = try writer.print("Illegal instruction at address 0x{X}", .{ addr });
},
.bus_error => |addr| {
_ = try writer.print("Bus error at address 0x{X}", .{ addr });
},
.floating_point_error => |addr| {
_ = try writer.print("Floating point error at address 0x{X}", .{ addr });
},
.datatype_misalignment => {
_ = try writer.writeAll("Unaligned memory access");
},
.stack_overflow => {
_ = try writer.writeAll("Stack overflow");
},
.zig_error => |e| {
_ = try writer.print("error.{s}", .{ @errorName(e) });
},
.out_of_memory => {
_ = try writer.writeAll("Bun ran out of memory");
},
}
    }
};

pub const Action = union(enum) {
    parse: []const u8,
    visit: []const u8,
    print: []const u8,
    bundle_generate_chunk: BundleGenerateChunkPayload,
    resolver: ResolverPayload,
    dlopen: []const u8,
    pub fn has(s: []const u8) bool { if (comptime @typeInfo(@This()).@"union".tag_type) |TagType| { return std.meta.stringToEnum(TagType, s) != null; } return false; }
    pub fn name(self: @This()) []const u8 { return @tagName(self); }

pub fn format(act: Action, writer: *std.Io.Writer) !void {
            switch (act) {
.parse => |path| {
_ = try writer.print("parsing {s}", .{ path });
},
.visit => |path| {
_ = try writer.print("visiting {s}", .{ path });
},
.print => |path| {
_ = try writer.print("printing {s}", .{ path });
},
.bundle_generate_chunk => |data| {
_ = (if (bun.Environment.show_crash_trace) blk: {
            const entry_text: ?[]const u8 = (if (data.part_range.source_index.isValid()) data.linkerContext().parse_graph.input_files.items(.source)[@as(usize, @intCast(data.chunk.entry_point.source_index))].path.text else null);
            const source_text: ?[]const u8 = (if (data.part_range.source_index.isValid()) data.linkerContext().parse_graph.input_files.items(.source)[@as(usize, @intCast(data.part_range.source_index.get()))].path.text else null);
            break :blk try writer.print("generating bundler chunk\n  chunk entry point: {?s}\n  source: {?s}\n  part range: {d}..{d}", .{ entry_text, source_text, data.part_range.part_index_begin, data.part_range.part_index_end });

} else null);
},
.resolver => |res| {
_ = (if (bun.Environment.show_crash_trace) blk: {
            break :blk try writer.print("resolving {s} from {s} ({s})", .{ res.import_path, res.source_dir, res.kind.label() });

} else null);
},
.dlopen => |path| {
_ = try writer.print("loading native module: {s}", .{ path });
},
}
    }
};

