pub fn handleSegfaultWindows(info: *windows.EXCEPTION_POINTERS) callconv(.winapi) c_long {
        const code = info.ExceptionRecord.ExceptionCode;
        if ((code == bun.windows.MS_VC_EXCEPTION)) {
            return bun.windows.EXCEPTION_CONTINUE_EXECUTION;
        }
        var reason: CrashReason = datatype_misalignment_reason;
        _ = &reason;
        if ((code == windows.EXCEPTION_DATATYPE_MISALIGNMENT)) {
            reason = datatype_misalignment_reason;
        } else {
            if ((code == windows.EXCEPTION_ACCESS_VIOLATION)) {
                reason = CrashReason{ .segmentation_fault = info.ExceptionRecord.ExceptionInformation[1] };
            } else {
                if ((code == windows.EXCEPTION_ILLEGAL_INSTRUCTION)) {
                    reason = CrashReason{ .illegal_instruction = info.ContextRecord.getRegs().ip };
                } else {
                    if ((code == windows.EXCEPTION_STACK_OVERFLOW)) {
                        reason = stack_overflow_reason;
                    } else {
                        return windows.EXCEPTION_CONTINUE_SEARCH;
                    }
                }
            }
        }
        _ = crashHandler(reason, null, @intFromPtr(info.ExceptionRecord.ExceptionAddress));
}

